    for(const t of D.tools.filter(x=>x.instId===i.id)){ t.instNombre = d.nuevo; t.hist = (t.hist||[]).concat([{f:now, t:`👷 El instalador cambió: ${d.anterior} → ${d.nuevo} · ${quien}`}]); await herrPut(t); }
