  const lista = `<ul style="margin:6px 0 0 18px;padding:0">${(l.consumo||[]).filter(c=>Number(c.cantidad)>0).map(c=>{ const it=CATALOGO.find(i=>i.id===c.itemId); return it?`<li>${fmtNum(c.cantidad)} ${it.unidad} ${it.nombre}</li>`:''; }).join('')}</ul>`;
