// Cuánto se gasta normalmente al día de un consumible (salidas del cierre del último mes).
function usoNormalCierre(itemId){
  const desde = new Date(Date.now()-30*86400000).toISOString(), mod = modulo();
  const cierres = movs.filter(m=>m.modulo===mod && m.cierreTurno && (m.fecha||'')>=desde && diaLocal(m.fecha)!==fechaHoyLocal());
  const dias = new Set(cierres.map(m=>diaLocal(m.fecha))).size;
  const total = cierres.filter(m=>m.itemId===itemId && m.tipo==='salida' && !m.anulado && m.estado!=='rechazado').reduce((s,m)=>s+(Number(m.cantidad)||0),0);
  return {dias, prom: dias ? total/dias : 0};
}
// ¿Lo que se usó hoy es raro? Con historial: más de 3 veces lo normal. Sin historial: más de la mitad de lo que había.
// Si el cierre de hoy junta varios días (no se hizo cierre antes), se compara lo de un día (v178).
function usoRaroCierre(itemId, uso, esp){
  if(!(uso>0)) return null;
  const {dias, prom} = usoNormalCierre(itemId);
  const nd = 1 + (cierreHechoHoy() ? 0 : diasSinCierre().length), porDia = uso/nd, extra = nd>1 ? ` (este cierre junta ${nd} días)` : '';
  if(dias>=5){ if(prom>0 ? (porDia > prom*3 && porDia-prom >= 2) : (esp>0 && uso > esp*0.25)) return {prom, txt: (prom>0 ? `Normalmente se usan ~${fmtNum(Math.round(prom*10)/10)} al día` : 'Normalmente no se usa')+extra}; return null; }
  return esp>0 && uso > esp*0.5 ? {prom:0, txt:`Es más de la mitad de lo que había`+extra} : null;
}
// Material de instalaciones y garantías recientes (ya descontado) por artículo.
function materialApartado(dias){
  const desde = new Date(Date.now()-(dias||3)*86400000).toISOString(), mod = modulo();
  return movs.filter(m=>m.modulo===mod && (m.tipo==='instalacion'||m.tipo==='garantia') && !m.anulado && cuentaEnInventario(m) && (m.fecha||'')>=desde);
}
function apartadoDe(itemId){ return materialApartado(3).filter(m=>m.itemId===itemId).reduce((s,m)=>s+(Number(m.cantidad)||0),0); }
const apartadoBadge = itemId => { const q = apartadoDe(itemId); return q>0 ? `<span title="De instalaciones de los últimos 3 días" style="display:inline-block;font-size:11px;font-weight:800;padding:2px 7px;border-radius:8px;margin-top:3px;background:rgba(124,58,237,.2);color:#c4b5fd;border:1px solid #7c3aed">📦 ${fmtNum(q)} apartado${q===1?'':'s'}</span>` : ''; };
function apartadosAudHtml(items){
  const ids = new Set(items.map(i=>i.id)), ms = materialApartado(3).filter(m=>ids.has(m.itemId)); if(!ms.length) return '';
  const lotes = {}; ms.forEach(m=>{ const k = m.loteId||m.id; (lotes[k] = lotes[k]||[]).push(m); });
  const ls = Object.values(lotes).sort((a,b)=>(b[0].fecha||'').localeCompare(a[0].fecha||''));
  const cuando = f => { const d = diaLocal(f), h = new Date(f).toLocaleTimeString('es-MX',{hour:'numeric',minute:'2-digit'}); return (d===fechaHoyLocal()?'hoy':d===diaLocal(new Date(Date.now()-86400000).toISOString())?'ayer':new Date(f).toLocaleDateString('es-MX',{day:'numeric',month:'short'}))+' '+h; };
  return `<div style="margin-top:10px;border-radius:14px;border:2px solid #7c3aed;background:rgba(124,58,237,.12);padding:12px"><div style="font-weight:900;font-size:15px;color:#c4b5fd">📦 Material de instalaciones recientes</div>
    <div class="hint" style="margin:3px 0 6px">Ya se descontó del inventario. Si <b>todavía está en el almacén</b> esperando que se lo lleven, <b>NO lo cuentes</b>.</div>
    ${ls.slice(0,12).map(g=>`<div style="padding:7px 0;border-top:1px solid rgba(124,58,237,.35)"><b>${g[0].tipo==='garantia'?'🛡️':'🏠'} ${herrEsc(String(g[0].nota||'Instalación').split(' · ')[0])}</b> <span class="hint" style="margin:0">${cuando(g[0].fecha)}</span><div class="hint" style="margin:2px 0 0">${g.map(m=>`${fmtNum(m.cantidad)} ${m.itemNombre}`).join(' · ')}</div></div>`).join('')}
    <div class="hint" style="margin:6px 0 0">Muestra lo de los últimos 3 días.</div></div>`;
}
function cierreMovsHoyHtml(){
  const mod = modulo(), R = movsDiaClasif(mod, fechaHoyLocal()), D = deudasDeModulo(mod);
  const hora = m => new Date(m.fecha).toLocaleTimeString('es-MX',{hour:'numeric',minute:'2-digit'});
  const fila = (x, sale, txt) => `<div class="row" style="justify-content:space-between;gap:8px;border-top:1px solid rgba(127,127,127,.25);padding:7px 0;flex-wrap:nowrap"><span style="min-width:0"><strong>${x.m.itemNombre}</strong><span class="hint" style="display:block;margin:0">${hora(x.m)} · ${txt}${x.m.estado==='pendiente'?' · ⏳ por aprobar':''}</span></span><strong style="white-space:nowrap;font-size:15px;color:${sale?'#f87171':'#4ade80'}">${sale?'−':'+'} ${fmtNum(x.m.cantidad)} ${item2unidad(x.m.itemId)}</strong></div>`;
  const caja = (ic, t, sub, col, cuerpo) => `<div style="margin-top:10px;border-radius:14px;border:2px solid ${col};background:${col}1a;padding:10px"><div style="font-weight:900;font-size:15px;color:${col}">${ic} ${t}</div><div class="hint" style="margin:0 0 2px">${sub}</div>${cuerpo}</div>`;
  const b = s => `<b>${s}</b>`;
  const prov = R.provEnt.map(x=>fila(x,false,'De '+b(x.quien))).concat(R.provSal.length ? [`<div style="margin-top:8px;padding:4px 8px;border-radius:8px;background:rgba(220,38,38,.25);color:#fca5a5;font-weight:800;font-size:13px">📤 Se regresó al proveedor (sale)</div>`].concat(R.provSal.map(x=>`<div style="background:rgba(220,38,38,.10);border-radius:8px;padding:0 6px">${fila(x,true,'A '+b(x.quien)+(x.porque?' · '+x.porque:''))}</div>`)) : []);
  const tras = R.prestamos.map(x=>fila(x,true,`🤝 Le prestamos a ${b(x.quien)} (nos debe)${x.porque?' · '+x.porque:''}`))
    .concat(R.nosPrestaron.map(x=>fila(x,false,`🤝 Nos prestó ${b(x.quien)} (le debemos)${x.porque?' · '+x.porque:''}`)))
    .concat(R.nosRegresaron.map(x=>fila(x,false,`↩️ ${b(x.quien)} nos regresó lo que le prestamos`)))
    .concat(R.regresamos.map(x=>fila(x,true,`↩️ Le regresamos a ${b(x.quien)} lo que nos prestó`)));
  const sinD = R.sinDeudaSal.map(x=>fila(x,true,'➜ '+b(x.quien)+(x.porque?' · '+x.porque:''))).concat(R.otrosEnt.map(x=>fila(x,false,'De '+b(x.quien)+' (sin préstamo)'))).concat(R.alm.map(x=>fila(x,false,'De '+b('Almacén general'))));
  const deu = (D.nosDeben.length||D.debemos.length) ? caja('⚖️', 'Cómo quedan las deudas de '+mod, 'Al día de hoy · en melamina cuenta cualquier color', '#0ea5e9',
      (()=>{ const blk = (xs, t, col) => { if(!xs.length) return ''; const mods = [...new Set(xs.map(x=>x.otro))];
          return `<div style="font-weight:800;color:${col};margin-top:6px">${t}</div>` + mods.map(md=>`<div style="padding:6px 0;border-top:1px solid rgba(127,127,127,.25)"><b>📍 ${md}</b><div class="hint" style="margin:2px 0 0">${xs.filter(x=>x.otro===md).map(x=>`• ${fmtNum(x.pend)} ${x.unidad} ${x.art}`).join(' &nbsp; ')}</div></div>`).join(''); };
        return blk(D.nosDeben, '💰 Nos deben', '#4ade80') + blk(D.debemos, '🧾 Debemos', '#f87171'); })()) : '';
  if(!prov.length && !tras.length && !sinD.length && !deu) return '<div id="cierre-movs"></div>';
  return `<div class="card" id="cierre-movs"><strong style="font-size:16px">🔄 Lo que hoy ya se movió</strong>
    <p class="hint" style="margin:2px 0 0">Ya está en el inventario: <strong>no lo cuentes como gastado</strong>.</p>
    ${prov.length?caja('🏭','Proveedores','Material que compramos o que regresamos','#16a34a',prov.join('')):''}
    ${tras.length?caja('🔄','Traspasos (préstamos)','Lo que prestamos o nos prestaron','#8b5cf6',tras.join('')):''}
    ${sinD.length?caja('📤','Salidas a otro módulo (sin deuda)','Se fue y no regresa','#ea580c',sinD.join('')):''}
    ${deu}</div>`;
}
// PDF: una sola hoja "Entradas y salidas del día" con los 4 apartados.
function dibujarMovsDiaPDF(doc, R, D, o){
  const L = o.marginL, W = o.W, pageH = o.pageH; let y = o.y;
  const VER=[22,128,74], MOR=[109,40,217], NAR=[194,65,12], AZU=[3,105,161], ROJ=[185,28,28];
  const tinte = (c,f) => c.map(v=>Math.round(v+(255-v)*f));
  const salto = h => { if(y + h > pageH-14){ doc.addPage(); y = 15; } };
  const banda = (t, sub, c) => { salto(26); doc.setFillColor(...c); doc.rect(L,y,W,13,'F'); doc.setTextColor(255,255,255); doc.setFont(undefined,'bold'); doc.setFontSize(12); doc.text(t, L+4, y+6); doc.setFont(undefined,'normal'); doc.setFontSize(8); doc.text(sub, L+4, y+10.8); doc.setTextColor(0,0,0); y += 16; };
  const subt = (t, c) => { salto(16); doc.setFont(undefined,'bold'); doc.setFontSize(10); doc.setTextColor(...c); doc.text(t, L, y+4); doc.setTextColor(0,0,0); doc.setFont(undefined,'normal'); y += 6; };
  const tabla = (cols, filas, c, x0=L, ancho=W) => { const tw = cols.reduce((s,k)=>s+k.w,0), f = ancho/tw, xs = []; let acc = x0; cols.forEach(k=>{ xs.push(acc); acc += k.w*f; });
    const head = () => { doc.setFillColor(...c); doc.rect(x0,y,ancho,6,'F'); doc.setTextColor(255,255,255); doc.setFont(undefined,'bold'); doc.setFontSize(7.8); cols.forEach((k,i)=>doc.text(k.t, xs[i]+1.5, y+4.2)); doc.setFont(undefined,'normal'); doc.setTextColor(0,0,0); y += 6; };
    salto(14); head();
    filas.forEach((fr,idx)=>{ doc.setFontSize(8.5); const ls = fr.map((v,i)=>doc.splitTextToSize(String(v.t!==undefined?v.t:v), cols[i].w*f-3).slice(0,3)); const h = Math.max(5.6, 1.9+Math.max(...ls.map(l=>l.length))*3.7);
      if(y+h > pageH-14){ doc.addPage(); y = 15; head(); }
      if(idx%2){ doc.setFillColor(...tinte(c,.92)); doc.rect(x0,y,ancho,h,'F'); }
      fr.forEach((v,i)=>{ const ob = (v && typeof v==='object') ? v : {}; if(ob.col) doc.setTextColor(...ob.col); if(ob.b) doc.setFont(undefined,'bold'); ls[i].forEach((l,k)=>doc.text(l, xs[i]+1.5, y+4+k*3.7)); doc.setFont(undefined,'normal'); doc.setTextColor(0,0,0); });
      y += h; }); y += 3; };
  const hora = m => new Date(m.fecha).toLocaleTimeString('es-MX',{hour:'numeric',minute:'2-digit'});
  const q = (x, sale) => ({t:(sale?'−':'+')+fmtNum(x.m.cantidad)+' '+item2unidad(x.m.itemId), b:true, col: sale?ROJ:VER});
  const fl = (xs, sale, conPorque) => xs.map(x=>[hora(x.m), x.m.itemNombre+(x.m.estado==='pendiente'?' (por aprobar)':''), q(x,sale), x.quien+(conPorque&&x.porque?' · '+x.porque:'')]);
  const C4 = t => [{t:'Hora',w:20},{t:'Artículo',w:62},{t:'Cantidad',w:30},{t:t,w:70}];
  // Totales arriba
  const nTr = R.prestamos.length+R.nosPrestaron.length+R.nosRegresaron.length+R.regresamos.length;
  const kp = [[R.provEnt.length+R.provSal.length,'de proveedores',VER],[nTr,'traspasos',MOR],[R.sinDeudaSal.length+R.otrosEnt.length+R.alm.length,'sin deuda / otros',NAR],[`${D.nosDeben.length} · ${D.debemos.length}`,'nos deben · debemos',AZU]];
  const kw = (W-9)/4; kp.forEach((k,i)=>{ const x = L+i*(kw+3); doc.setFillColor(...tinte(k[2],.9)); doc.rect(x,y,kw,14,'F'); doc.setFillColor(...k[2]); doc.rect(x,y,1.4,14,'F'); doc.setFont(undefined,'bold'); doc.setFontSize(13); doc.setTextColor(...k[2]); doc.text(String(k[0]), x+3.5, y+6.5); doc.setFont(undefined,'normal'); doc.setFontSize(7.5); doc.setTextColor(90,96,112); doc.text(k[1], x+3.5, y+11.5); }); doc.setTextColor(0,0,0); y += 18;
  const vacio = t => { doc.setFontSize(9); doc.setTextColor(120,124,136); doc.text(t, L+2, y+3); doc.setTextColor(0,0,0); y += 7; };
  banda('1. Proveedores', 'Material que compramos (entra) o que regresamos al proveedor (sale)', VER);
  if(!R.provEnt.length && !R.provSal.length) vacio(o.vacioTxt('Sin movimientos con proveedores'));
  if(R.provEnt.length){ subt('Llegó (entra)', VER); tabla(C4('Proveedor'), fl(R.provEnt,false), VER); }
  if(R.provSal.length){ subt('Se regresó al proveedor (sale)', ROJ); tabla(C4('Proveedor · por qué'), fl(R.provSal,true,true), ROJ); }
  banda('2. Traspasos entre módulos (préstamos)', 'Lo prestado se debe regresar · en melamina cuenta cualquier color', MOR);
  if(!nTr) vacio(o.vacioTxt('Sin traspasos'));
  if(R.prestamos.length){ subt('Le prestamos a otro módulo (sale · nos deben)', MOR); tabla(C4('A quién · nota'), fl(R.prestamos,true,true), MOR); }
  if(R.nosPrestaron.length){ subt('Nos prestaron (entra · debemos)', MOR); tabla(C4('Quién · nota'), fl(R.nosPrestaron,false,true), MOR); }
  if(R.nosRegresaron.length){ subt('Nos regresaron lo que prestamos (entra · ya nos pagaron)', MOR); tabla(C4('Quién'), fl(R.nosRegresaron,false), MOR); }
  if(R.regresamos.length){ subt('Regresamos lo que nos prestaron (sale · ya pagamos)', MOR); tabla(C4('A quién'), fl(R.regresamos,true), MOR); }
  banda('3. Salidas a otro módulo (sin deuda) y otras entradas', 'Se fue y no se regresa · o llegó de otro lado sin préstamo', NAR);
  if(!R.sinDeudaSal.length && !R.otrosEnt.length && !R.alm.length) vacio(o.vacioTxt('Sin salidas a otros módulos'));
  if(R.sinDeudaSal.length){ subt('Salió (sin deuda)', NAR); tabla(C4('A dónde · por qué'), fl(R.sinDeudaSal,true,true), NAR); }
  if(R.otrosEnt.length || R.alm.length){ subt('Entró (sin préstamo)', NAR); tabla(C4('De dónde'), fl(R.alm.concat(R.otrosEnt),false,true), NAR); }
  banda('4. Cómo quedan las deudas de '+o.mod, 'Al día de hoy (no solo de este día) · en melamina cuenta cualquier color', AZU);
  if(!D.nosDeben.length && !D.debemos.length) vacio('No hay deudas pendientes con otros módulos.');
  else { const y0 = y, mitad = (W-6)/2; let yA = y0, yB = y0;
    const blk = (xs, t, c, x0) => { y = y0; doc.setFont(undefined,'bold'); doc.setFontSize(10); doc.setTextColor(...c); doc.text(t, x0, y+4); doc.setTextColor(0,0,0); doc.setFont(undefined,'normal'); y += 6;
      if(!xs.length){ doc.setFontSize(9); doc.setTextColor(120,124,136); doc.text('Nada', x0+2, y+3); doc.setTextColor(0,0,0); y += 7; }
      else tabla([{t:'Módulo',w:24},{t:'Artículo',w:44},{t:'Pendiente',w:24}], xs.map(x=>[x.otro, x.art, {t:fmtNum(x.pend)+' '+x.unidad, b:true, col:c}]), c, x0, mitad); return y; };
    yA = blk(D.nosDeben, 'Nos deben', VER, L); yB = blk(D.debemos, 'Debemos', ROJ, L+mitad+6); y = Math.max(yA, yB); }
  return y;
}
function renderCierre(){
  corrAutoJuntar();
  if(!cierrePrestOk){ cierrePrestOk = true; cargarPrestamos().then(()=>{ const el = document.getElementById('cierre-movs'); if(el && current==='cierre'){ const t = document.createElement('div'); t.innerHTML = cierreMovsHoyHtml(); el.replaceWith(t.firstElementChild); } }); }
  if(esSoloLectura()){ $('#main').innerHTML='<div class="card">Tu cuenta es de solo lectura.</div>'; return; }
  const hojas = CATALOGO.filter(i=>esHoja(i));
  const cp = cortesPendientes();
  const conMaterial = hojas.filter(it=>{ const f=calcFormulaConPendientes(it.id); return f.completas>0.0005 || (f.autoCortes||0)>0 || !vacioCierre(cierreVals[it.id]); });
  const visibles = cierreTodasHojas ? hojas : conMaterial;
  $('#main').innerHTML = `<div class="card">
      <div style="font-size:17px;font-weight:800">📝 Cierre del turno · ${modulo()}</div>
      <p class="hint">Tubos, bridas, correderas, jaladeras, bisagras, espejos, rieles, sistemas y bastidores <strong>ya se descontaron solos</strong> con las instalaciones y garantías. Aquí solo va lo demás.</p>
      ${cierreHechoHoy()?'<p class="hint" style="color:var(--ok)">✅ Ya capturaste un cierre hoy. Puedes agregar más si faltó algo.</p>':''}
      ${(()=>{ const ds = cierreHechoHoy() ? [] : diasSinCierre(); return ds.length ? `<p style="margin:10px 0 0;padding:9px 11px;border-radius:10px;background:rgba(37,99,235,.12);border:1px solid rgba(37,99,235,.5);font-size:14px">📆 Este cierre incluye <strong>${ds.length+1} días</strong> (${diasCortosTxt(ds.slice(-4))}${ds.length>4?'…':''} y hoy): no se hizo cierre antes. Cuenta lo que te queda como siempre.</p>` : ''; })()}
    </div>
    <div id="cierre-avisos"></div>
    ${cierreRepetidasHtml()}
    ${cierreMovsHoyHtml()}
    <div class="card">
      <div class="paso">1</div><strong>✂️ ¿Cuántas hojas completas te quedan?</strong>
      <p class="hint">Cuenta las hojas <strong>completas</strong> (sin cortar) de cada color y escríbelo. La app calcula sola cuántas se cortaron. El total del inventario no cambia: solo pasan de completas a cortadas.${cp.length?` <br>Pendiente de anotar: ${cp.map(x=>fmtNum(x.f.autoCortes)+' '+x.it.nombre.replace('Melamina ','')).join(', ')}.`:''}</p>
      <div class="movlist" style="margin-top:8px">${visibles.map(filaConteoHoja).join('') || '<p class="hint">No hay hojas completas registradas.</p>'}</div>
      ${hojas.length>conMaterial.length?`<button class="btn small" style="margin-top:8px;background:transparent;color:var(--brand);border:1px solid var(--line);box-shadow:none" onclick="cierreTodasHojas=!cierreTodasHojas;renderCierre()">${cierreTodasHojas?'Ver solo los que tienen material':'Ver todos los colores ('+hojas.length+')'}</button>`:''}
    </div>
    <div class="card">
      <div class="paso">2</div><strong>📦 ¿Cuánto te queda?</strong>
      <p class="hint">Cuenta lo que tienes <strong>ahora</strong> y escríbelo. La app calcula cuánto se usó y lo descuenta. Deja vacío lo que no contaste.</p>
      <div class="chips" style="margin-top:8px">${CIERRE_CATS.map(c=>{ const n=CATALOGO.filter(i=>i.cat===c && esConsumibleCierre(i) && !vacioCierre(cierreVals[i.id])).length; return `<button class="chip ${c===cierreCat&&!cierreBuscar?'on':''}" onclick="cierreCat='${c}';cierreBuscar='';cierreTodosCons=false;renderCierre()">${ICONO_CAT[c]||''} ${c==='Herrajes'?'Pijas y demás':c}${n?' ✓'+n:''}</button>`; }).join('')}</div>
      <input type="search" placeholder="🔍 Buscar (ej. pijas, cintilla blanco)" value="${String(cierreBuscar).replace(/"/g,'&quot;')}" style="margin-top:8px" oninput="cierreBuscar=this.value;renderCierreConsumibles()">
      <div class="movlist" id="cierre-cons" style="margin-top:8px"></div>
      <p class="hint" id="cierre-cuenta" style="margin-top:6px">${cuentaCierreTxt()}</p>
    </div>
    ${herrConfHtml()}
    <div class="card">
      <input id="cierre-nota" placeholder="Nota (opcional)">
      <button class="btn" style="margin-top:12px;width:100%;min-height:54px;font-size:16px" onclick="guardarCierre()">✅ Guardar cierre del turno</button>
    </div>`;
  renderCierreConsumibles();
  ['n','e'].forEach(corrPintarRes);
  coordAvisosPintarCierre();
  if(!herrHoyLogs) db.collection('instalacionesLog').get().then(sn=>{ herrHoyLogs = sn.docs.map(d=>({id:d.id,...d.data()})).filter(l=>l.modulo===modulo()); herrConfPintar(); }).catch(()=>{ herrHoyLogs = []; });
}
// Solo los artículos que tienen material (o que ya se escribieron); los demás con "Ver todos" (v178).
let cierreTodosCons = false;
function renderCierreConsumibles(){
  const el = document.getElementById('cierre-cons'); if(!el) return;
  const q = cierreBuscar.trim();
  const delCat = CATALOGO.filter(i=>esConsumibleCierre(i) && (q ? coincide(i.nombre, q) : i.cat===cierreCat));
  const cons = (q || cierreTodosCons) ? delCat : delCat.filter(i=>stockEsperadoCierre(i.id)>0.0005 || !vacioCierre(cierreVals[i.id]));
  const nombreCat = cierreCat==='Herrajes' ? 'pijas y demás' : cierreCat.toLowerCase();
  const boton = !q && delCat.length>cons.length ? `<button class="btn small" style="margin-top:8px;background:transparent;color:var(--brand);border:1px solid var(--line);box-shadow:none" onclick="cierreTodosCons=true;renderCierreConsumibles()">Ver todos (${delCat.length}) · ¿no ves alguno?</button>`
    : (!q && cierreTodosCons && delCat.some(i=>!(stockEsperadoCierre(i.id)>0.0005))) ? `<button class="btn small" style="margin-top:8px;background:transparent;color:var(--brand);border:1px solid var(--line);box-shadow:none" onclick="cierreTodosCons=false;renderCierreConsumibles()">Ver solo los que tienen material</button>` : '';
  el.innerHTML = (cons.map(filaCierreConteo).join('') || `<p class="hint">${q ? 'No se encontró.' : 'La app no tiene '+nombreCat+' en '+modulo()+'.'}</p>`) + boton;
}
async function guardarCierre(){
  if(!confirmarModuloDir()) return; // Dirección: ¿es el módulo correcto? (v178)
  const herrIts = herrConfItems(), herrSin = herrIts.filter(it=>!herrConf[it.id] || herrConf[it.id].ok===undefined);
  if(herrSin.length){ const el=document.getElementById('herrconf-card'); if(el) el.scrollIntoView({behavior:'smooth'}); return alert('🔩 Falta contestar si tienes estos herrajes:\n\n'+herrSin.map(it=>'• '+it.nombre+(CORR_CALC[it.nombre]?' (llena todas las casillas de la calculadora; pon 0 si no tienes)':'')).join('\n')); }
  { const cz = ['n','e'].map(k=>corrResultado(k)); if(cz.every(r=>r.completo && r.juegos===0 && r.sobH===0 && r.sobM===0) && !confirm('🔩 En las dos calculadoras de correderas pusiste todo en 0.\n\n¿Seguro que no tienes ninguna corredera?')) return; }
  const herrMal = herrIts.filter(it=>herrConf[it.id].ok===false && !(String(herrConf[it.id].tiene).trim()!=='' && Number(herrConf[it.id].tiene)>=0));
  if(herrMal.length) return alert('🔩 Escribe cuántos tienes de:\n\n'+herrMal.map(it=>'• '+it.nombre).join('\n'));
  const herrajes = herrIts.map(it=>{ const r = herrConf[it.id];
    if(r.corr){ const e = r.corr.esp, x = r.corr.r; return {itemId:it.id, nombre:it.nombre, unidad:'juego', esperado:e.juegos, ok:r.ok, tiene:fmtNum(x.juegos),
      corr:{esp:{J:e.J, H:e.H, M:e.M, juegos:e.juegos, hembras:e.hembras, machos:e.machos}, r:{juegos:fmtNum(x.juegos), sobH:fmtNum(x.sobH), sobM:fmtNum(x.sobM)}, det:x.det}}; }
    const esp = fmtNum(stockEsperadoCierre(it.id)); return {itemId:it.id, nombre:it.nombre, unidad:it.unidad||'', esperado:esp, ok:r.ok, tiene: r.ok ? esp : fmtNum(Number(r.tiene))}; });
  const herrNo = herrajes.filter(h=>!h.ok);
  const nota = (document.getElementById('cierre-nota').value||'').trim();
  const hojasContadas = CATALOGO.filter(i=>esHoja(i) && !vacioCierre(cierreVals[i.id]));
  for(const it of hojasContadas){ const v=Number(cierreVals[it.id]); if(!(v>=0)) return alert(`Revisa lo que escribiste en ${it.nombre}.`); }
  const conteoHojas = hojasContadas.map(it=>Object.assign({it}, corteDesdeConteo(it.id, cierreVals[it.id])));
  const cortes = conteoHojas.filter(x=>x.corte>0).map(x=>({it:x.it, q:x.corte, esp:x.esp, contadas:x.contadas}));
  const hojasDeMas = conteoHojas.filter(x=>x.deMas>0);
  const contados = CATALOGO.filter(i=>esConsumibleCierre(i) && !vacioCierre(cierreVals[i.id]));
  for(const it of contados){ const v=Number(cierreVals[it.id]); if(!(v>=0)) return alert(`Revisa lo que escribiste en ${it.nombre}.`); }
  const salidas = [], deMas = [], iguales = [];
  contados.forEach(it=>{ const esp = stockEsperadoCierre(it.id), hay = Number(cierreVals[it.id]); const d = fmtNum(esp - hay);
    if(d>0) salidas.push({it, q:d, esp, hay}); else if(d<0) deMas.push({it, esp, hay}); else iguales.push(it); });
  const repsHoy = entradasRepetidasHoy(modulo());
  if(repsHoy.length && !confirm(`🔁 Hoy hay ${repsHoy.length} entrada(s) que parecen anotadas dos veces (${repsHoy.slice(0,3).map(xs=>xs[0].itemNombre).join(', ')}${repsHoy.length>3?'…':''}).\n\nSi haces el cierre así, lo repetido se toma como gastado.\n\n¿Hacer el cierre de todos modos?`)) return;
  const raros = salidas.map(x=>Object.assign({}, x, {raro:usoRaroCierre(x.it.id, x.q, x.esp)})).filter(x=>x.raro);
  if(raros.length && !confirm(`⚠️ Revisa, esto es mucho más de lo normal:\n\n${raros.map(x=>`• ${x.it.nombre}: se usaron ${fmtNum(x.q)} ${x.it.unidad} · ${x.raro.txt}`).join('\n')}\n\n¿Estás seguro? Si llegó material o se anotó una entrada doble, corrígelo antes.\n\nAceptar = sí, está bien · Cancelar = revisar`)) return;
  if(!hojasContadas.length && !contados.length && !herrNo.length){
    if(!confirm('No escribiste nada.\n\n¿Hoy no se cortaron hojas y no quieres contar consumibles?\n\nAceptar = sí, guardar "sin movimiento" para que no te lo vuelva a recordar hoy.')) return;
  }
  if(hojasContadas.length || contados.length){
    const txt = `Cierre del turno:\n\n`
      + (cortes.length ? '✂️ Se cortaron (pasan de completas a cortado):\n'+cortes.map(c=>`• ${fmtNum(c.q)} ${c.it.nombre} (quedan ${fmtNum(c.contadas)} completas)`).join('\n')+'\n\n' : '')
      + (hojasDeMas.length ? '⚠️ Hay MÁS hojas completas de las que dice la app (se avisa a Dirección para que lo revise):\n'+hojasDeMas.map(x=>`• ${x.it.nombre}: app ${fmtNum(x.esp)}, tú ${fmtNum(x.contadas)}`).join('\n')+'\n\n' : '')
      + (salidas.length ? '📤 Se usó (se descuenta):\n'+salidas.map(x=>`• ${fmtNum(x.q)} ${x.it.unidad} ${x.it.nombre} (había ${fmtNum(x.esp)}, quedan ${fmtNum(x.hay)})`).join('\n')+'\n\n' : '')
      + (iguales.length ? `✔️ Sin cambio: ${iguales.length} artículo(s)\n\n` : '')
      + (deMas.length ? '⚠️ Tienes MÁS de lo que dice la app (no se toca; si llegó material, anótalo en "Llegó material"):\n'+deMas.map(x=>`• ${x.it.nombre}: app ${fmtNum(x.esp)}, tú ${fmtNum(x.hay)}`).join('\n')+'\n\n' : '')
      + (herrNo.length ? '🔩 Herrajes que NO cuadran (le llega a Dirección, no cambia el inventario):\n'+herrNo.map(h=>`• ${h.nombre}: inventario ${h.esperado}, tienes ${h.tiene}`).join('\n')+'\n\n' : '')
      + '¿Guardar?';
    if(!confirm(txt)) return;
  }
  try{
    const creadoPor = getCurrentUserEmail?getCurrentUserEmail():'', fecha = new Date().toISOString(), mod = modulo();
    const loteC = cryptoId(), loteS = cryptoId();
    for(const c of cortes) await db.collection('movimientos').doc(cryptoId()).set({modulo:mod, itemId:c.it.id, itemNombre:c.it.nombre, tipo:'corte', cantidad:c.q, nota:`Cierre del turno: quedan ${fmtNum(c.contadas)} completas`+(nota?' · '+nota:''), fecha, estado:'aprobado', loteId:loteC, creadoPor, cierreTurno:true, conteoCompletas:{esperado:c.esp, contado:c.contadas}});
    // Hojas completas de más: no se tocan solas; van a Dirección como ajuste por aprobar.
    const loteA = cryptoId();
    for(const x of hojasDeMas) await db.collection('movimientos').doc(cryptoId()).set({modulo:mod, itemId:x.it.id, itemNombre:x.it.nombre, tipo:'ajuste', motivo:'cierreCompletasDeMas', cantidad:x.deMas, completasDelta:x.deMas, cortadoDelta:0, nota:`Cierre del turno: la app esperaba ${fmtNum(x.esp)} completas y contaron ${fmtNum(x.contadas)}`+(nota?' · '+nota:''), fecha, estado:'pendiente', loteId:loteA, creadoPor, cierreTurno:true});
    const estado = 'aprobado'; // Cierre del turno entra directo, sin aprobación (confirmado por el usuario)
    for(const x of salidas) await db.collection('movimientos').doc(cryptoId()).set({modulo:mod, itemId:x.it.id, itemNombre:x.it.nombre, tipo:'salida', cantidad:x.q, nota:`Cierre del turno: había ${fmtNum(x.esp)}, quedan ${fmtNum(x.hay)}`+(nota?' · '+nota:''), fecha, estado, loteId:loteS, creadoPor, cierreTurno:true, conteoCierre:{esperado:x.esp, contado:x.hay}});
    if(!cortes.length && !salidas.length) await db.collection('movimientos').doc(cryptoId()).set({modulo:mod, itemId:'_cierre', itemNombre:'Cierre sin movimiento', tipo:'nota', cantidad:0, nota:'Cierre del turno sin movimiento'+(nota?' · '+nota:''), fecha, estado:'aprobado', loteId:cryptoId(), creadoPor, cierreTurno:true});
    // Aviso a Dirección: el módulo ya hizo su cierre del turno.
    try{ await db.collection('cierres').doc(cryptoId()).set({modulo:mod, fecha, dia:fechaHoyLocal(), creadoPor, nota,
      cortes:cortes.map(c=>({nombre:c.it.nombre, q:c.q})), hojasDeMas:hojasDeMas.map(x=>({nombre:x.it.nombre, q:x.deMas})),
      consumibles:salidas.length, consDeMas:deMas.map(x=>x.it.nombre), hojasContadas:hojasContadas.length, herrajes, herrNo:herrNo.length}); }catch(e){}
    cierreVals = {}; cierreBuscar = ''; herrConf = {}; herrHoyLogs = null; corrCalc = {n:{}, e:{}};
    toast('✅ Cierre del turno guardado.'+(hojasDeMas.length?'<br><small>Las hojas de más las revisa Dirección.</small>':''));
    setView('home');
  }catch(e){ alert('Error: '+e.message); }
}
let _cierreAvisado = null;
